        "自分さえも"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "命令　故意を感じて",
        "訂正　無為を観じて",
        "安寧は罪が混ざる",
        "当然か"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "知った顔で笑っててよ",
        "底知らず恐れるの",
        "月並みの愛をくれよ",
        "You know me",
        "知った気で踊ってるの",
        "底が満たされるの",
        "放さないで止めないで",
        "独りじゃないの"
      ]
    }
  ],
  "section": "V2",
  "phrases": [
    {
      "id": "V2-01",
