      "ja": "自分さえも",
      "budget": {
        "min": 5,
        "max": 5
      },
      "pattern": [
        5
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "潜藏的忧愁啊"
        },
        {
          "id": "V2-02",
          "zh": "怎么也无法坦率"
        },
        {
          "id": "V2-03",
          "zh": "和谁都难以相互理解"
        },
        {
          "id": "V2-04",
          "zh": "连自己也是"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "闷在心底的 那一层忧"
        },
        {
          "id": "V2-02",
          "zh": "话到嘴边 又咽回心里"
        },
        {
          "id": "V2-03",
          "zh": "说给空气 没人接住的话"
        },
        {
          "id": "V2-04",
          "zh": "自己也不懂"
        }
      ]
    },
